<?php
namespace App\Http\Controllers;
use App\Http\Requests\StoreTransportVehicleRequest;use App\Models\TransportVehicle;use App\Services\TransportAuditService;
class TransportVehicleController extends Controller {public function index(){return view('transport.vehicles.index',['vehicles'=>TransportVehicle::forCompany(auth()->user()->company_id)->latest()->paginate(20)]);}public function store(StoreTransportVehicleRequest $r,TransportAuditService $audit){$v=TransportVehicle::create($r->validated()+['company_id'=>$r->user()->company_id,'created_by'=>$r->user()->id]);$audit->record($v->company_id,'transport_vehicle_created','vehicle',$v->id,$r->user()->id);return back()->with('success','Vehículo registrado.');}public function update(StoreTransportVehicleRequest $r,TransportVehicle $vehicle,TransportAuditService $audit){$this->own($vehicle);$vehicle->update($r->validated()+['updated_by'=>$r->user()->id]);$audit->record($vehicle->company_id,'transport_vehicle_updated','vehicle',$vehicle->id,$r->user()->id);return back()->with('success','Vehículo actualizado.');}public function destroy(TransportVehicle $vehicle,TransportAuditService $audit){$this->own($vehicle);$vehicle->update(['status'=>'inactive','updated_by'=>auth()->id()]);$audit->record($vehicle->company_id,'transport_vehicle_deactivated','vehicle',$vehicle->id,auth()->id());return back()->with('success','Vehículo desactivado sin eliminar su historial.');}private function own($m):void{abort_unless((int)$m->company_id===(int)auth()->user()->company_id,404);}}
